import math
import sys
import string
t = int(input())
while t:
	n = int(input())
	arr = [0] * n
	arr[0] = [int(x) for x in input().split()]
	for i in range(1, n):
		arr[0][i] += arr[0][i - 1]
	for i in range(1, n):
		arr[i] = [int(x) for x in input().split()]
		arr[i][0] += arr[i - 1][0]
		for j in range(1, n):
			arr[i][j] += max(arr[i][j - 1], arr[i - 1][j])
	if arr[n - 1][n - 1] < 0:
		print('Bad Judges')
	else:
		print('%.6f' % (arr[n - 1][n - 1] / (2 * n - 3)))
	t -= 1
